contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(address target, uint value, bytes memory data) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(address(this).balance >= value);

        c.sendMoney(target, value, data); if (__ESBMC_reverted()) return;

        uint finalBalance = address(c).balance;
        uint finalDeposits = c.depositsCount(); if (__ESBMC_reverted()) return;

        assert(
            finalBalance + value >= finalBalance &&
            finalDeposits == 0
        );
    }

    receive() external payable {}
}

